1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export type StepResult =
41	  | { premium: number }
42	  | { payout: number; remainingCap: number };
43	
44	export interface ScenarioResult {
45	  results: StepResult[];
46	}
47	
48	const PROCESSING_FEE = 5;
49	const FIRST_INSURANCE_SURCHARGE = 0.1;
50	
51	const BASE_PREMIUMS: Record<string, number> = {
52	  sword: 100,
53	  amulet: 60,
54	};
55	
56	const quotePremium = (step: QuoteStep): number => {
57	  const basePremium = step.items.reduce(
58	    (sum, item) => sum + BASE_PREMIUMS[item.type],
59	    0,
60	  );
61	  return (
62	    basePremium + basePremium * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE
63	  );
64	};
65	
66	export const runScenario = (scenario: Scenario): ScenarioResult => ({
67	  results: scenario.steps.map((step) => ({
68	    premium: quotePremium(step as QuoteStep),
69	  })),
70	});
